import billing, gateway, settlement
class Fake:
    def __init__(self, script):
        self.script, self.charges, self.keys, self.calls = list(script), {}, {}, 0
    def create_charge(self, order_id, amount_cents, idempotency_key=None):
        self.calls += 1
        step = self.script.pop(0) if self.script else 'ok'
        if step == 'lost':
            raise gateway.GatewayTimeout(order_id)
        if idempotency_key is not None and idempotency_key in self.keys:
            charge_id = self.keys[idempotency_key]
        else:
            charge_id = 'ch_%d' % (len(self.charges) + 1)
            self.charges[charge_id] = (order_id, amount_cents)
            if idempotency_key is not None:
                self.keys[idempotency_key] = charge_id
        if step == 'late':
            raise gateway.GatewayTimeout(order_id)
        return charge_id
